INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Managing a personal or business budget effectively requires careful planning and regular review. Many people find it helpful to track their expenses each month, separating essential costs such as rent and utilities from optional spending like entertainment or dining out. Setting clear financial goals, whether saving for a large purchase or building an emergency fund, can provide motivation to stick to a budget over time. Unexpected expenses will inevitably arise, so keeping a small reserve set aside can prevent financial stress when they occur. Reviewing spending habits regularly also helps identify areas where small changes could lead to meaningful savings. With consistent effort, most people can gain better control over their finances within just a few months."}'::jsonb, '{"exact": "Managing a personal or business budget effectively requires careful planning and regular review. Many people find it helpful to track their expenses each month, separating essential costs such as rent and utilities from optional spending like entertainment or dining out. Setting clear financial goals, whether saving for a large purchase or building an emergency fund, can provide motivation to stick to a budget over time. Unexpected expenses will inevitably arise, so keeping a small reserve set aside can prevent financial stress when they occur. Reviewing spending habits regularly also helps identify areas where small changes could lead to meaningful savings. With consistent effort, most people can gain better control over their finances within just a few months."}'::jsonb, 123, 0.52, 'B2', 'approved', 'exam', 'finance', 'c4000000-0000-4000-8000-000000000011', 1);
