INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Noor noticed a discrepancy in the monthly report. She traced the error back to a duplicate entry. After correcting the mistake, the figures finally matched. Her manager thanked her for catching it before the audit."}'::jsonb, '{"key_points": ["Noor noticed a discrepancy", "she traced it to a duplicate entry", "she corrected the mistake", "her manager thanked her before the audit"]}'::jsonb, 34, 0.50, 'B1', 'approved', 'exam', 'finance', 'c4000000-0000-4000-8000-000000000014', 1),
('passage_reconstruction', '{"passage": "Said had been preparing the annual budget for weeks. During the review meeting, the board asked for several adjustments. He revised the figures and presented them again the next day. The board approved the budget without further changes."}'::jsonb, '{"key_points": ["Said prepared the budget for weeks", "the board asked for adjustments", "he revised and represented it the next day", "the board approved it"]}'::jsonb, 37, 0.54, 'B2', 'approved', 'exam', 'finance', 'c4000000-0000-4000-8000-000000000014', 2),
('passage_reconstruction', '{"passage": "Thank you for your patience while we processed your refund request. The payment has now been issued and should reach your account within five business days. Please contact us if you do not see it by then."}'::jsonb, '{"key_points": ["thanks for patience with the refund", "payment issued, arrives within five business days", "invites contact if not received"]}'::jsonb, 36, 0.52, 'B1', 'approved', 'exam', 'finance', 'c4000000-0000-4000-8000-000000000014', 3),
('passage_reconstruction', '{"passage": "I am writing to remind you that your quarterly payment is due by the end of this week. Please let us know if you need any assistance completing the transfer. We appreciate your continued business."}'::jsonb, '{"key_points": ["reminds about the quarterly payment due this week", "offers assistance with the transfer", "thanks them for continued business"]}'::jsonb, 34, 0.50, 'B1', 'approved', 'exam', 'finance', 'c4000000-0000-4000-8000-000000000014', 4);
INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "You work in the finance department. Your manager, Ms. Novak, wants to reduce late payments from clients. Write an email to her suggesting three ways to achieve this. Your suggestions must come from the following three themes: automated payment reminders, early payment discounts, clearer invoice terms. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.55, 'B2', 'approved', 'exam', 'finance', 'c4000000-0000-4000-8000-000000000015', 1),
('email_writing', '{"prompt": "You work at an accounting firm. A client, Mr. Osei, was charged twice for the same service by mistake. Write an email to him apologizing and explaining the correction. Your response must address the following three themes: an apology for the error, confirmation of the refund timeline, reassurance it will not happen again. You should include all three themes with a clear, professional tone."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'finance', 'c4000000-0000-4000-8000-000000000015', 2);
